  `metaDescription` text COLLATE utf8mb4_unicode_ci,
  `targetArea` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `faqJson` text COLLATE utf8mb4_unicode_ci,
  `albumJson` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Portfolio_slug_key` (`slug`),
  KEY `Portfolio_featured_createdAt_idx` (`featured`,`createdAt`),
  KEY `Portfolio_createdAt_idx` (`createdAt`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
